function LessonCard({ id, title, learn, status, onStart }) {
 const badgeColor = status === 'completed'? '#4ade80' : status === 'current'? '#61dafb' : '#94a3b8';
 const badgeText = status === 'completed'? 'COMPLETED' : status === 'current'? 'CURRENT' : 'LOCKED';

 return (
 <div style={{background: 'rgba(15,31,51,0.88)', border: '1px solid rgba(97,218,251,0.16)', borderRadius: '20px', padding: '22px', margin: '10px'}}>
 <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
 <span style={{color: '#61dafb', fontSize: '11px', fontWeight: '800'}}>LESSON {String(id).padStart(2,'0')}</span>
 <span style={{color: badgeColor, background: badgeColor+'20', padding: '5px 8px', borderRadius: '999px', fontSize: '10px', fontWeight: '800'}}>{badgeText}</span>
 </div>
 <h3 style={{fontSize: '20px', margin: '13px 0', color: 'white'}}>{title}</h3>
 <p style={{color: '#94a3b8', fontSize: '13px'}}>What you will learn: {learn}</p>
 {status!== 'locked'? (
 <button onClick={() => onStart(id)} style={{background: 'linear-gradient(135deg, #61dafb, #0ea5e9)', border: 'none', borderRadius: '11px', padding: '10px 15px', fontWeight: '800', marginTop: '15px', cursor: 'pointer'}}>Start Lesson →</button>
 ) : (
 <button disabled style={{background: 'rgba(71,85,105,0.45)', color: '#cbd5e1', border: 'none', borderRadius: '11px', padding: '10px 15px', marginTop: '15px'}}>🔒 Locked</button>
 )}
 </div>
 );
}

function App() {
 const lessons = [
 {id: 1, title: "Introduction to React", learn: "Understand what React is and Virtual DOM", status: "completed"},
 {id: 2, title: "JSX and Components", learn: "Create reusable components with JSX", status: "completed"},
 {id: 3, title: "Props and Communication", learn: "Pass data between components with props", status: "current"},
 {id: 4, title: "State and Interaction", learn: "Make UI interactive with state", status: "locked"},
 {id: 5, title: "React Hooks", learn: "Use useState and useEffect like a pro", status: "locked"},
 ];

 function handleStart(id) {
 alert("Opening Lesson " + id + " - In real app, navigate to /lesson/" + id);
 }

 return (
 <div style={{background: '#07111f', minHeight: '100vh', padding: '20px', fontFamily: 'Inter'}}>
 <h1 style={{color: 'white'}}>React Development Lessons</h1>
 <p style={{color: '#94a3b8'}}>{lessons.filter(l => l.status==='completed').length} / {lessons.length} completed</p>
 <div style={{display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '18px', marginTop: '20px'}}>
 {lessons.map(lesson => (
 <LessonCard key={lesson.id} id={lesson.id} title={lesson.title} learn={lesson.learn} status={lesson.status} onStart={handleStart} />
 ))}
 </div>
 <p style={{color: '#61dafb', marginTop: '20px'}}>YOUR CHALLENGE: Add Lesson 6 object to array and see new card appear automatically!</p>
 </div>
 );
}

export default App;
